import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { act, renderHook, waitFor } from "@testing-library/react";
import React from "react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type * as ApiModule from "../api";
import { initInspectorStore, inspectorStore } from "../store";
import { useConversationData } from "./useConversationData";

const mockGetBotData = vi.fn();
vi.mock("../api", async (importOriginal) => {
  const actual = await importOriginal<typeof ApiModule>();
  return {
    ...actual,
    getBotData: (...args: unknown[]) => mockGetBotData(...args) as unknown,
  };
});

function renderUseConversationData() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });

  const renderResult = renderHook(() => useConversationData(), {
    wrapper: ({ children }: { children: React.ReactNode }) =>
      React.createElement(QueryClientProvider, { client: queryClient }, children),
  });

  return { ...renderResult, queryClient };
}

describe("useConversationData", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    initInspectorStore();
    mockGetBotData.mockResolvedValue({ flows: {}, assistant_id: "test" });
  });

  it("calls getBotData with httpAuth from store when set", async () => {
    initInspectorStore({
      projectUrl: "http://localhost:5005",
      botDataEndpoint: "/data",
      httpAuth: { token: "secret-token", via: "query" },
    });

    renderUseConversationData();

    await waitFor(() => {
      expect(mockGetBotData).toHaveBeenCalledWith({
        projectUrl: "http://localhost:5005",
        botDataEndpoint: "/data",
        httpAuth: { token: "secret-token", via: "query" },
      });
    });
  });

  it("calls getBotData without httpAuth when not set in store", async () => {
    initInspectorStore({
      projectUrl: "http://localhost:5005",
      botDataEndpoint: "/data",
    });

    renderUseConversationData();

    await waitFor(() => {
      expect(mockGetBotData).toHaveBeenCalledWith({
        projectUrl: "http://localhost:5005",
        botDataEndpoint: "/data",
        httpAuth: undefined,
      });
    });
  });

  it("skips flow conversion and stores the catalog for Mantle projects", async () => {
    mockGetBotData.mockResolvedValue({
      // A flow with steps would normally be converted into store.flows.
      flows: {
        travel_notice: { description: "", steps: [{ id: "a", action: "utter_a" }] },
      },
      assistant_id: "test",
      engine: "mantle",
      skills: {},
    });
    initInspectorStore({ projectUrl: "http://localhost:5005", botDataEndpoint: "/data" });

    renderUseConversationData();

    await waitFor(() => {
      expect(inspectorStore.state.engineType).toBe("mantle");
    });
    expect(inspectorStore.state.skillCatalog).toEqual({});
    // The flows conversion is skipped because the engine is Mantle, not
    // because a skills catalog happens to be present.
    expect(inspectorStore.state.flows).toEqual([]);
  });

  it("stays in calm mode for v1 payloads without the engine field", async () => {
    mockGetBotData.mockResolvedValue({
      // No `engine` key: a released v1 project must keep the flow pipeline
      // intact and map to calm.
      flows: {
        travel_notice: { description: "", steps: [{ id: "a", action: "utter_a" }] },
      },
      assistant_id: "test",
    });
    initInspectorStore({ projectUrl: "http://localhost:5005", botDataEndpoint: "/data" });

    renderUseConversationData();

    await waitFor(() => {
      expect(inspectorStore.state.flows).toHaveLength(1);
    });
    expect(inspectorStore.state.engineType).toBe("calm");
    expect(inspectorStore.state.skillCatalog).toBeNull();
  });

  it("refetches when authToken changes while projectUrl stays the same", async () => {
    initInspectorStore({
      projectUrl: "http://localhost:5005",
      botDataEndpoint: "/data",
      httpAuth: { token: "token-A", via: "header" },
    });

    renderUseConversationData();

    await waitFor(() => {
      expect(mockGetBotData).toHaveBeenCalledWith(
        expect.objectContaining({ httpAuth: { token: "token-A", via: "header" } }),
      );
    });

    act(() => {
      inspectorStore.setState((prev) => ({
        ...prev,
        httpAuth: { token: "token-B", via: "header" },
      }));
    });

    await waitFor(() => {
      expect(mockGetBotData).toHaveBeenCalledWith(
        expect.objectContaining({ httpAuth: { token: "token-B", via: "header" } }),
      );
    });
    expect(mockGetBotData).toHaveBeenCalledTimes(2);
  });

  it("refetches when only the transport changes", async () => {
    initInspectorStore({
      projectUrl: "http://localhost:5005",
      botDataEndpoint: "/data",
      httpAuth: { token: "same-token", via: "query" },
    });

    renderUseConversationData();

    await waitFor(() => expect(mockGetBotData).toHaveBeenCalledTimes(1));

    act(() => {
      inspectorStore.setState((prev) => ({
        ...prev,
        httpAuth: { token: "same-token", via: "header" },
      }));
    });

    await waitFor(() => {
      expect(mockGetBotData).toHaveBeenCalledWith(
        expect.objectContaining({ httpAuth: { token: "same-token", via: "header" } }),
      );
    });
    expect(mockGetBotData).toHaveBeenCalledTimes(2);
  });

  it("keeps the token out of the query key", async () => {
    initInspectorStore({
      projectUrl: "http://localhost:5005",
      botDataEndpoint: "/data",
      httpAuth: { token: "secret-session-token", via: "header" },
    });

    const { queryClient } = renderUseConversationData();

    await waitFor(() => expect(mockGetBotData).toHaveBeenCalled());

    const queryKeys = queryClient
      .getQueryCache()
      .getAll()
      .map((query) => JSON.stringify(query.queryKey));
    for (const key of queryKeys) {
      expect(key).not.toContain("secret-session-token");
    }
  });

  it("refetches when botDataEndpoint changes while projectUrl stays the same", async () => {
    initInspectorStore({
      projectUrl: "http://localhost:5005",
      botDataEndpoint: "/data",
    });

    renderUseConversationData();

    await waitFor(() => {
      expect(mockGetBotData).toHaveBeenCalledWith(
        expect.objectContaining({ botDataEndpoint: "/data" }),
      );
    });

    act(() => {
      inspectorStore.setState((prev) => ({
        ...prev,
        botDataEndpoint: "/data-v2",
      }));
    });

    await waitFor(() => {
      expect(mockGetBotData).toHaveBeenCalledWith(
        expect.objectContaining({ botDataEndpoint: "/data-v2" }),
      );
    });
    expect(mockGetBotData).toHaveBeenCalledTimes(2);
  });
});
